def seed_knowledge_base() -> int:
    inserted = 0
    with SessionLocal.begin() as db:
        existing = set(db.scalars(select(KnowledgeEntry.seed_key)).all())
        for item in SEED_ENTRIES:
            if item.key in existing:
                continue
            db.add(KnowledgeEntry(
                seed_key=item.key,
                category=item.category,
                title=item.title,
                content=item.content,
                next_action=item.action,
                tags=item.tags,
                needs_review=item.review,
                source_sheet=item.sheet,
                source_rows=item.rows,
                sort_order=item.order,
            ))
            inserted += 1
    return inserted
